sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    source_recommendation();
    source_vulnerability_explanation();
    source_vulnerability_summary();

    function source_vulnerability_summary() {
        var endPoint;
        //Get Authorization val
        var gri = new GlideRecord('sn_sec_int_impl_config');
        gri.addEncodedQuery('implementation=' + "bacbac81330c12506f51b1945d5c7bf7" + '^configuration=6fbf705c83295210b9b19b00feaad30e');
        gri.query();

        //Get API-Key val
        var grk = new GlideRecord('sn_sec_int_impl_config');
        grk.addEncodedQuery('implementation=' + "bacbac81330c12506f51b1945d5c7bf7" + '^configuration=3a1f705c83295210b9b19b00feaad360');
        grk.query();

        //Get API EndPoint val
        var org = new GlideRecord('sn_sec_int_impl_config');
        org.addEncodedQuery('implementation=' + "bacbac81330c12506f51b1945d5c7bf7" + '^configuration=13ff309c83295210b9b19b00feaad319');
        org.query();
        if (org.next()) {
            var grURL = new GlideRecord('sn_sec_int_impl_config');
            grURL.addEncodedQuery('implementation=' + "bacbac81330c12506f51b1945d5c7bf7" + '^configuration=a46f705c83295210b9b19b00feaad3ae');
            grURL.query();
            if (grURL.next()) {
                endPoint = "https://" + grURL.value + "/Contrast/api/ng/" + org.value + "/traces/" + current.source_avit_id + "/story?expand=skip_links";
            }

        }

        var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'Recommendations');
        r.setEndpoint(endPoint);
        if (gri.next() && grk.next()) {
            r.setRequestHeader('API-Key', grk.value); //Load API-Key
            r.setRequestHeader('Authorization', gri.value); //Load Authorization

        }
        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        if (httpStatus == 200 || httpStatus == 201) {
            ;
            var res = JSON.parse(responseBody);
            current.source_vulnerability_summary = res.story.risk.text;
        }

    }

    function source_vulnerability_explanation() {
        var endPoint;

        // Get Authorization value
        var gri = new GlideRecord('sn_sec_int_impl_config');
        gri.addEncodedQuery('implementation=bacbac81330c12506f51b1945d5c7bf7^configuration=6fbf705c83295210b9b19b00feaad30e');
        gri.query();
        var authorization = gri.next() ? gri.value : null;

        // Get API-Key value
        var grk = new GlideRecord('sn_sec_int_impl_config');
        grk.addEncodedQuery('implementation=bacbac81330c12506f51b1945d5c7bf7^configuration=3a1f705c83295210b9b19b00feaad360');
        grk.query();
        var apiKey = grk.next() ? grk.value : null;

        // Get Organization ID
        var org = new GlideRecord('sn_sec_int_impl_config');
        org.addEncodedQuery('implementation=bacbac81330c12506f51b1945d5c7bf7^configuration=13ff309c83295210b9b19b00feaad319');
        org.query();
        var organizationId = org.next() ? org.value : null;

        // Get Base URL
        var grURL = new GlideRecord('sn_sec_int_impl_config');
        grURL.addEncodedQuery('implementation=bacbac81330c12506f51b1945d5c7bf7^configuration=a46f705c83295210b9b19b00feaad3ae');
        grURL.query();
        var baseURL = grURL.next() ? grURL.value : null;

        if (authorization && apiKey && organizationId && baseURL) {
            endPoint = "https://" + baseURL + "/Contrast/api/ng/" + organizationId + "/traces/" + current.source_avit_id + "/story?expand=skip_links";

            var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'Recommendations');
            r.setEndpoint(endPoint);
            r.setRequestHeader('API-Key', apiKey);
            r.setRequestHeader('Authorization', authorization);

            try {
                var response = r.execute();
                var httpStatus = response.getStatusCode();

                if (httpStatus == 200 || httpStatus == 201) {
                    var res = JSON.parse(response.getBody());
                    var chapters = res.story && res.story.chapters ? res.story.chapters : [];
                    var chapterOutput = "";

                    chapters.forEach(function(chapter) {
                        var introText = chapter.introText || "";
                        var body = chapter.body || "";
                        chapterOutput += introText + "\n" + body + "\n";
                    });
                    // Remove only end new lines
                    chapterOutput = chapterOutput.replace(/\n+$/, '');
                    // Replace remaining new lines with <br> for display
                    chapterOutput = chapterOutput.replace(/\n/g, '<br>');

                    current.source_vulnerability_explanation = chapterOutput;
                } else {
                    gs.error("Failed with status: " + httpStatus);
                }
            } catch (error) {
                gs.error("REST API call failed: " + error.message);
            }
        } else {
            gs.error("One or more required configuration values are missing.");
        }
    }

    function source_recommendation() {

        var endPoint;
        //Get Authorization val
        var gri = new GlideRecord('sn_sec_int_impl_config');
        gri.addEncodedQuery('implementation=' + "bacbac81330c12506f51b1945d5c7bf7" + '^configuration=6fbf705c83295210b9b19b00feaad30e');
        gri.query();

        //Get API-Key val
        var grk = new GlideRecord('sn_sec_int_impl_config');
        grk.addEncodedQuery('implementation=' + "bacbac81330c12506f51b1945d5c7bf7" + '^configuration=3a1f705c83295210b9b19b00feaad360');
        grk.query();

        //Get API EndPoint val
        var org = new GlideRecord('sn_sec_int_impl_config');
        org.addEncodedQuery('implementation=' + "bacbac81330c12506f51b1945d5c7bf7" + '^configuration=13ff309c83295210b9b19b00feaad319');
        org.query();
        if (org.next()) {
            var grURL = new GlideRecord('sn_sec_int_impl_config');
            grURL.addEncodedQuery('implementation=' + "bacbac81330c12506f51b1945d5c7bf7" + '^configuration=a46f705c83295210b9b19b00feaad3ae');
            grURL.query();
            if (grURL.next()) {
                endPoint = "https://" + grURL.value + "/Contrast/api/ng/" + org.value + "/traces/" + current.source_avit_id + "/recommendation?expand=skip_links";

            }

        }

        var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'Recommendations');
        r.setEndpoint(endPoint);
        if (gri.next() && grk.next()) {
            r.setRequestHeader('API-Key', grk.value); //Load API-Key
            r.setRequestHeader('Authorization', gri.value); //Load Authorization

        }
        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        if (httpStatus == 200 || httpStatus == 201) {
            var res = JSON.parse(responseBody);
            current.source_recommendation = res.recommendation.text;



        }
    }
    current.integration = "Contrast IAST List Integration";


    current.update();
})(current, previous);
